            failed++;
            console.error(`[启动器] ❌ ${script.name} 加载失败:`, e);
        }
        if (loaded + failed === toLoad.length) {
            console.log(`[启动器 ${VERSION}] 🎉 加载完成: ${loaded} 成功, ${failed} 失败`);
        }
    });
})();

(function () {
  const SCRIPT_ID = typeof getScriptId === 'function' ? getScriptId() : 'tide_choice_foldable';
  const SAFE_ID = String(SCRIPT_ID).replace(/[^a-zA-Z0-9_-]/g, '_');
  const STYLE_ID = `tide-choice-style-${SAFE_ID}`;
  const OWNER = `tide-choice-${SAFE_ID}`;
  const GLOBAL_KEY = `__tideChoiceController_${SAFE_ID}`;
  const STORAGE_KEY = `tide-choice-collapsed-${SAFE_ID}`;
  const DIRECT_SEND_KEY = `tide-choice-directsend-${SAFE_ID}`;

  // ---------- 简洁 CSS ----------
  const CSS = String.raw`
    .mes_text choice { display: none !important; }

    .tide-choice-card {
      position: relative;
      width: 100%;
      margin: 8px 0 4px;
      border: 1px solid rgba(127, 201, 255, 0.3);
