    .tide-choice-card * { box-sizing: border-box; }

    /* 头部 - 可折叠点击区域 */
    .tide-header {
      display: flex;
      align-items: center;
      gap: 10px;
      padding: 10px 14px;
      background: rgba(13, 43, 69, 0.7);
      border-bottom: 1px solid rgba(127,201,255,0.2);
