    }
    .tide-header:hover { background: rgba(20, 60, 90, 0.7); }
    .tide-header-icon { width: 18px; height: 18px; color: #7fc9ff; flex-shrink: 0; }
    .tide-header-title {
      font-size: 12px;
      font-weight: 600;
      letter-spacing: 0.8px;
      color: #a8e6ff;
      flex: 1;
    }
    .tide-header-controls {
      display: flex;
      align-items: center;
      gap: 8px;
      flex-shrink: 0;
    }
    .tide-toggle-label {
      font-size: 11px;
      color: #8bb8d8;
    }
    .tide-toggle-switch {
      width: 34px;
      height: 20px;
      background: rgba(127,201,255,0.15);
      border: 1px solid rgba(127,201,255,0.3);
      border-radius: 10px;
