      background: rgba(127,201,255,0.3);
      border-color: #7fc9ff;
    }
    .tide-toggle-switch::after {
      content: '';
      position: absolute;
      top: 2px;
      left: 2px;
      width: 14px;
      height: 14px;
      background: #8bb8d8;
      border-radius: 50%;
      transition: transform 0.12s;
    }
    .tide-toggle-switch.active::after {
      transform: translateX(14px);
      background: #7fc9ff;
    }
    .tide-collapse-indicator {
      font-size: 16px;
      color: #7fc9ff;
      transition: transform 0.25s;
      margin-left: 4px;
    }
    .tide-collapse-indicator.collapsed { transform: rotate(-90deg); }

    /* 选项面板 - 折叠控制 */
    .tide-options-panel {
      max-height: 600px;
      overflow: hidden;
      transition: max-height 0.35s ease, padding 0.35s ease, opacity 0.25s ease;
      padding: 12px 14px;
      opacity: 1;
    }
    .tide-choice-card.collapsed .tide-options-panel {
      max-height: 0;
